function escapeHtml(value = '') {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function pickFirst(...values) {
  for (const value of values) {
    if (value === undefined || value === null) continue;
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (typeof value === 'number' && Number.isFinite(value)) return String(value);
    if (typeof value === 'object') {
      try {
        const asText = JSON.stringify(value);
        if (asText && asText !== '{}' && asText !== '[]') return asText;
      } catch (e) {}
    }
  }
  return '';
}

function toText(value) {
  if (value === undefined || value === null) return '';
  if (typeof value === 'string') return value;
  try {
    return JSON.stringify(value);
  } catch (e) {
    return String(value);
  }
}

function shortText(value, limit = 1800) {
  const text = toText(value);
  if (text.length <= limit) return text;
  return text.slice(0, limit) + '\n...';
}

function normalize(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .trim();
}

const input = $input.item.json || {};
const owner = String($env.OWNER_DISPLAY_NAME || 'User').trim();

const workflowName = pickFirst(
  input.workflow?.name,
  input.workflowName,
  input.execution?.workflowName,
  input.execution?.workflow?.name,
  input.trigger?.workflow?.name,
  'Không rõ workflow'
);

const workflowId = pickFirst(
  input.workflow?.id,
  input.workflowId,
  input.execution?.workflowId,
  input.execution?.workflow?.id,
  input.trigger?.workflow?.id
);

const executionId = pickFirst(
  input.execution?.id,
  input.executionId,
  input.trigger?.execution?.id
);

const executionUrl = pickFirst(
  input.execution?.url,
  input.executionUrl,
  input.trigger?.execution?.url
);

const lastNode = pickFirst(
  input.execution?.lastNodeExecuted,
  input.lastNodeExecuted,
  input.node?.name,
  input.error?.node?.name,
  input.execution?.error?.node?.name
);

const errorMessage = pickFirst(
  input.execution?.error?.message,
  input.error?.message,
  input.message,
  input.execution?.error
);

const errorDescription = pickFirst(
  input.execution?.error?.description,
  input.error?.description,
  input.errorDescription
);

const errorName = pickFirst(
  input.execution?.error?.name,
  input.error?.name,
  input.name
);

const stack = pickFirst(
  input.execution?.error?.stack,
  input.error?.stack,
  input.stack
);

const mode = pickFirst(
  input.execution?.mode,
  input.mode
);

const startedAt = pickFirst(
  input.execution?.startedAt,
  input.startedAt,
  input.timestamp,
  new Date().toISOString()
);

const wf = normalize(workflowName);
const node = normalize(lastNode);
const err = normalize([errorName, errorMessage, errorDescription, stack].filter(Boolean).join('\n'));

const parentWorkflowPatterns = [
  'master router',
  'semantic router',
  'ai chatbot',
  'bot tong',
  'bot tổng',
  'master',
  'router'
];

const childCallingNodePatterns = [
  'goi luong',
  'gọi luồng',
  'goi workflow',
  'gọi workflow',
  'execute workflow',
  'sub-workflow',
  'sub workflow',
  'goi sub',
  'gọi sub',
  'call workflow'
];

const childFailureErrorPatterns = [
  'workflow',
  'sub-workflow',
  'execution',
  'error in workflow',
  'workflow execution',
  'called workflow',
  'sub workflow'
];

const forceNotifyWorkflowPatterns = [
  'error monitor',
  'doctor'
];

function matchesAny(text, patterns) {
  return patterns.some((pattern) => text.includes(normalize(pattern)));
}

const isParentLike = matchesAny(wf, parentWorkflowPatterns);
const isCallingChildNode = matchesAny(node, childCallingNodePatterns);
const looksLikeChildFailed = matchesAny(err, childFailureErrorPatterns);
const isMonitorSelf = matchesAny(wf, forceNotifyWorkflowPatterns);

const currentExecutionId = pickFirst(
  input.execution?.id,
  input.executionId,
  input.trigger?.execution?.id
);

const propagatedExecutionId = pickFirst(
  input.execution?.error?.errorResponse?.executionId,
  input.execution?.error?.errorResponse?.context?.executionId
);

const isParentCascade = !isMonitorSelf && !!propagatedExecutionId && propagatedExecutionId !== currentExecutionId;

function classifySeverity(message, nodeName, workflow) {
  const text = normalize(`${message}\n${nodeName}\n${workflow}`);

  if (
    text.includes('chat_id is empty') ||
    text.includes('unauthorized') ||
    text.includes('forbidden') ||
    text.includes('credential') ||
    text.includes('invalid or unexpected token') ||
    text.includes('cannot read properties of undefined') ||
    text.includes('cannot read property') ||
    text.includes('missing') ||
    text.includes('bad request') ||
    text.includes('unable to parse range') ||
    text.includes('documents/:batchupdate') ||
    text.includes('insertion index') ||
    text.includes('parse entities')
  ) {
    return 'high';
  }

  if (
    text.includes('timeout') ||
    text.includes('not found') ||
    text.includes('rate limit') ||
    text.includes('too many requests') ||
    text.includes('network') ||
    text.includes('econnrefused') ||
    text.includes('enotfound')
  ) {
    return 'medium';
  }

  return 'medium';
}

function guessCause(message, nodeName, workflow) {
  const text = normalize(`${message || ''}\n${nodeName || ''}\n${workflow || ''}`);

  const rules = [
    {
      code: 'MISSING_CHAT_ID',
      test: () => text.includes('chat_id is empty') || text.includes('missing chatid'),
      cause: 'Thiếu chatId khi gửi Telegram. Kiểm tra Format Action/Prepare Action có giữ chatId qua các node API không.',
      fix: 'Luôn return và merge { chatId } sau Search/API/Format. Node gửi Telegram dùng {{$json.chatId}}.'
    },
    {
      code: 'TELEGRAM_HTML_PARSE',
      test: () => text.includes("can't parse entities") || text.includes('parse entities') || text.includes('unsupported start tag'),
      cause: 'Telegram parse_mode HTML lỗi do nội dung động chưa escape hoặc có tag HTML không hợp lệ.',
      fix: 'Escape mọi nội dung động bằng escapeHtml(); chỉ dùng tag Telegram hỗ trợ như b, i, code, pre, a.'
    },
    {
      code: 'JS_SYNTAX',
      test: () => text.includes('invalid or unexpected token') || text.includes('syntaxerror'),
      cause: 'Code node có lỗi JavaScript syntax. Hay gặp nhất là string xuống dòng trực tiếp trong dấu nháy đơn/kép.',
      fix: 'Dùng \\n hoặc template string hợp lệ; tránh paste text nhiều dòng vào string thường.'
    },
    {
      code: 'SHEETS_RANGE',
      test: () => text.includes('unable to parse range') || text.includes('sheet1'),
      cause: 'Google Sheets range sai hoặc đang hard-code Sheet1 trong file không có tab Sheet1.',
      fix: 'Mặc định dùng A1:Z30/A:Z/B2; chỉ thêm sheetTab khi user truyền tab cụ thể.'
    },
    {
      code: 'DOCS_MISSING_DOCUMENT_ID',
      test: () => text.includes('documents/:batchupdate') || text.includes('missing documentid'),
      cause: 'Google Docs API thiếu documentId trong URL batchUpdate.',
      fix: 'URL phải là /documents/{documentId}:batchUpdate; lấy documentId từ search/resolve trước.'
    },
    {
      code: 'DOCS_INSERT_INDEX',
      test: () => text.includes('insertion index') || text.includes('location') || text.includes('index must be inside'),
      cause: 'Google Docs append thiếu location.index hoặc index nằm ngoài document.',
      fix: 'Gọi documents.get trước, lấy body.content cuối cùng endIndex - 1, rồi build request insertText.'
    },
    {
      code: 'CONTEXT_UNDEFINED',
      test: () => text.includes('cannot read properties of undefined') || text.includes('cannot read property'),
      cause: 'Node đang đọc field không tồn tại. Thường do Telegram không có message.text khi gửi file/caption, hoặc output API mất context.',
      fix: 'Dùng optional chaining và fallback: message.text || message.caption || rawText; merge lại context sau API node.'
    },
    {
      code: 'API_BAD_REQUEST',
      test: () => text.includes('bad request') || text.includes('400'),
      cause: 'API trả Bad Request. Thường sai URL, body, query parameter, hoặc thiếu ID.',
      fix: 'Mở execution node lỗi, kiểm tra request URL/body preview và output raw error.'
    },
    {
      code: 'AUTH_PERMISSION',
      test: () => text.includes('unauthorized') || text.includes('forbidden') || text.includes('credential') || text.includes('scope'),
      cause: 'Lỗi quyền/credential/API scope.',
      fix: 'Kiểm tra credential, scopes, quyền truy cập file/folder, và token còn hợp lệ không.'
    },
    {
      code: 'NOT_FOUND',
      test: () => text.includes('not found') || text.includes('404'),
      cause: 'Không tìm thấy tài nguyên. Có thể sai fileId/documentId/spreadsheetId hoặc search không ra kết quả.',
      fix: 'Kiểm tra ID đầu vào và node Resolve Search Result.'
    },
    {
      code: 'NETWORK_TIMEOUT',
      test: () => text.includes('timeout') || text.includes('econnrefused') || text.includes('enotfound') || text.includes('network'),
      cause: 'Lỗi network/service không phản hồi.',
      fix: 'Kiểm tra network, endpoint, container/service local, timeout và retry policy.'
    }
  ];

  for (const rule of rules) {
    if (rule.test()) return rule;
  }

  return {
    code: 'UNKNOWN',
    cause: 'Chưa đoán chắc nguyên nhân. Cần mở execution để xem input/output node lỗi.',
    fix: 'Mở execution link, kiểm tra node lỗi, input, request body, response body và stack trace.'
  };
}

const severity = classifySeverity(`${errorMessage}\n${errorDescription}`, lastNode, workflowName);
const diagnosis = guessCause(`${errorMessage}\n${errorDescription}\n${stack}`, lastNode, workflowName);

const chatId = pickFirst(
  input.chatId,
  input.adminChatId,
  $env.TELEGRAM_ADMIN_CHAT_ID,
  input.execution?.data?.chatId
);

const isDevOrTest = /\b(test|draft|dev|sandbox)\b/i.test(String(workflowName || ''));

const skipNotify = isParentCascade;
let skipReason = skipNotify
  ? `Bỏ qua alert cha vì lỗi đã được báo từ child execution ${propagatedExecutionId}.`
  : '';

let text = '🚨 <b>n8n Workflow Error</b>\n\n';

text += `Workflow: <b>${escapeHtml(workflowName)}</b>\n`;

if (workflowId) {
  text += `Workflow ID: <code>${escapeHtml(workflowId)}</code>\n`;
}

if (lastNode) {
  text += `Node lỗi: <code>${escapeHtml(lastNode)}</code>\n`;
}

if (executionId) {
  text += `Execution ID: <code>${escapeHtml(executionId)}</code>\n`;
}

if (startedAt) {
  text += `Time: <code>${escapeHtml(startedAt)}</code>\n`;
}

if (mode) {
  text += `Mode: <code>${escapeHtml(mode)}</code>\n`;
}

if (executionUrl) {
  text += `🔗 <a href="${escapeHtml(executionUrl)}">Mở execution</a>\n`;
}

text += `Severity: <b>${escapeHtml(severity.toUpperCase())}</b>\n`;
text += `Diagnosis: <code>${escapeHtml(diagnosis.code)}</code>\n`;

text += '\n<b>Lỗi:</b>\n';
text += `<pre>${escapeHtml(shortText(errorMessage || 'Không rõ lỗi', 1600))}</pre>\n`;

if (errorDescription) {
  text += '\n<b>Mô tả:</b>\n';
  text += `<pre>${escapeHtml(shortText(errorDescription, 1200))}</pre>\n`;
}

text += '\n<b>Gợi ý nhanh:</b>\n';
text += `${escapeHtml(diagnosis.cause)}\n`;
text += `Fix: ${escapeHtml(diagnosis.fix)}\n`;

if (isParentCascade) {
  text += '\n<i>Ghi chú: Đây có vẻ là lỗi cascade ở workflow cha. Mia vẫn gửi tin này để ' + owner + ' xem đầy đủ ngữ cảnh.</i>\n';
}

if (stack && !isParentCascade) {
  text += '\n<b>Stack rút gọn:</b>\n';
  text += `<pre>${escapeHtml(shortText(stack, 1200))}</pre>`;
}

return [{
  json: {
    ...input,
    chatId,
    text: text.trim(),
    response: text.trim(),
    skipNotify,
    skipReason,
    isParentCascade,
    isDevOrTest,
    severity,
    diagnosisCode: diagnosis.code,
    workflowName,
    workflowId,
    executionId,
    executionUrl,
    lastNode,
    errorMessage,
    errorDescription,
    errorName,
    startedAt
  }
}];

